  "test": "import pytest
from langfuse.api.core.http_sse._models import ServerSentEvent

def test_server_sent_event_json_success():
    evt = ServerSentEvent(data='{"key": "value"}')
    assert evt.json() == {"key": "value"}

def test_server_sent_event_json_invalid_raises_value_error():
    evt = ServerSentEvent(data='not a json')
    with pytest.raises(ValueError) as exc_info:
        evt.json()
    assert "Invalid JSON in ServerSentEvent data" in str(exc_info.value)
    assert "not a json" in str(exc_info.value)
